<?php
namespace App\Http\Controllers\Api;
use App\Domain\Forms\Models\FormSubmission; use Illuminate\Http\Request; use Illuminate\Support\Str; use App\Http\Controllers\Controller; use App\Support\Audit\Audit;
class FormsController extends Controller { public function store(Request $request,string $type){$rules=['contact'=>['name'=>'required|string|max:120','email'=>'required|email','message'=>'required|string|max:5000'],'sponsorship'=>['name'=>'required|string|max:120','email'=>'required|email','message'=>'required|string|max:5000'],'tryouts'=>['name'=>'required|string|max:120','email'=>'required|email','message'=>'required|string|max:5000'],'newsletter'=>['email'=>'required|email']]; abort_unless(isset($rules[$type]),404); $data=$request->validate($rules[$type]+['consent'=>'accepted','website'=>'nullable|size:0']); if(!empty($data['website'])) return response()->json(['message'=>'Solicitud rechazada.'],422); $s=FormSubmission::create(['public_id'=>(string)Str::uuid(),'form_type'=>$type,'name'=>$data['name']??null,'email'=>$data['email']??null,'message'=>$data['message']??null,'payload'=>$data,'consent_at'=>now(),'ip_address'=>$request->ip(),'user_agent'=>$request->userAgent()]); Audit::write('forms','submitted',$s); return response()->json(['id'=>$s->public_id,'message'=>'Solicitud recibida.'],202); } }
